package com.aliothmoon.maafw.once;
import java.nio.file.*;
import org.junit.Test;
import static org.junit.Assert.*;
/** v24: old Projection route remains unreachable; its helpers retain their prior contracts. Root display is separately bounded. Source contracts only. They do not simulate Activity, BAL, Looper or MediaProjection. */
public class AutonomousWiringContractTest {
 private String source(String f)throws Exception {Path root=Path.of(System.getProperty("staging.root","."));Path p=root.resolve("app/src/main/java/com/aliothmoon/maafw/once/"+f);if(!Files.exists(p))p=Path.of(System.getProperty("authority.root","."),"app/src/main/java/com/aliothmoon/maafw/once/"+f);if(!Files.exists(p))p=Path.of(System.getProperty("working.root",".."),"app/src/main/java/com/aliothmoon/maafw/once/"+f);return Files.readString(p);}
 @Test public void businessLegacyEntrypointsRemainDisabled()throws Exception{String s=source("CaptureSessionRuntime.java");assertTrue(s.contains("v20 read-only profile: business input route disabled"));assertTrue(s.contains("v16 verification-only build: account input route disabled"));assertTrue(s.contains("static CaptureSessionRuntime startAutonomous("));}
 @Test public void oneExactOwnTaskRequestNoInjectedLifecycle()throws Exception{String s=source("DormantCaptureConfirmationActivity.java");String legacy=s.substring(s.indexOf("private void restoreOwnTaskForAutonomousAfter()"),s.indexOf("private void tryAutomaticAfter()"));assertEquals(1,legacy.split("own\\.moveToFront\\(\\)",-1).length-1);String root=s.substring(s.indexOf("private void restoreOwnTaskForRootDisplay("),s.indexOf("private AutonomousStageRoute autonomousRoute"));assertEquals(1,root.split("own\\.moveToFront\\(\\)",-1).length-1);assertTrue(s.contains("getComponentName().equals(info.baseActivity)"));assertTrue(s.contains("getComponentName().equals(info.topActivity)"));assertTrue(s.contains("autonomousRoute.requestRestore(autonomousRun,true)"));assertTrue(s.contains("autonomousRoute.onStart(autonomousRun,automaticAfterEligible())"));assertTrue(s.contains("autonomousRoute.claimSecond(autonomousRun,true,true)"));}
 @Test public void newProofBindsOriginalRunAndPrivateContinuation()throws Exception{String s=source("VisibleCaptureAuthority.java"),a=source("DormantCaptureConfirmationActivity.java");assertTrue(s.contains("activity.autonomousApprovalMatches(run,phase,click)"));assertTrue(s.contains("long deadline=run.deadline(now)"));assertTrue(a.contains("autonomousRoute.consume(incoming.continuation,exact,exact.current())"));assertTrue(a.contains("if(state!=null"));assertTrue(a.contains("click=new LiveClick(this,continuation)"));}
 @Test public void exactLifecycleAndCandidatesGateBusiness()throws Exception{String s=source("CaptureSessionRuntime.java");assertTrue(s.contains("candidate!=null&&released&&life!=null&&life.confirmedDestruction()"));assertTrue(s.contains("ports.projectionReturned()&&ports.consentRequestCode()>0"));assertTrue(s.contains("candidate=eligible?resultText:null"));assertTrue(s.contains("((readOnlyRun==null&&autonomousRun==null)||candidate!=null)"));assertTrue(s.contains("cardPhase==NativeRewardCardSession.Phase.AFTER"));}
 @Test public void finalMainCommitAndFirstHistoryPreserved()throws Exception{String s=source("DormantCaptureConfirmationActivity.java");assertTrue(s.contains("runtime.publicationCurrent()) && receipt.commit"));assertTrue(s.contains("firstAutonomousReceipt=receipt.history()"));assertTrue(s.contains("if(published)restoreOwnTaskForAutonomousAfter()"));assertTrue(s.contains("autonomousRun.returnReady()"));assertTrue(s.contains("stageDeadlines.removeCallbacksAndMessages(null)"));}
 @Test public void initialAttemptSpentBeforePotentiallyFailingRunConstruction()throws Exception{String s=source("DormantCaptureConfirmationActivity.java");String block=s.substring(s.indexOf("private void confirmRoot(RootCaptureScope.Mode mode)"),s.indexOf("void showRootFinalStatus"));assertTrue(block.indexOf("rootPreflightSpent=true")<block.indexOf("NativeAutonomousCardRun.confirmed"));assertTrue(block.indexOf("rootBusinessSpent=true")<block.indexOf("NativeAutonomousCardRun.confirmed"));assertTrue(block.indexOf("consumed=true")<block.indexOf("NativeAutonomousCardRun.confirmed"));assertTrue(s.contains("v24禁止旧Projection业务入口。"));}
 @Test public void delayedMainQueueCannotExtendOwnRestoreTimeout()throws Exception{String s=source("DormantCaptureConfirmationActivity.java");assertTrue(s.contains("ownRestoreDeadline=android.os.SystemClock.elapsedRealtime()+5000L"));assertTrue(s.contains("android.os.SystemClock.elapsedRealtime()<ownRestoreDeadline"));}
 @Test public void rejectedPageStillReportsOnlySafeTerminalScalars()throws Exception{String s=source("CaptureSessionRuntime.java");assertTrue(s.contains("+\" \"+autonomousRun.terminalSummary()"));assertFalse(s.contains("candidate=autonomousRun.terminalSummary()"));assertTrue(s.contains("candidate=eligible?resultText:null"));}
 @Test public void disclosedTargetBudgetAndSystemConsent()throws Exception{String s=source("AutonomousCaptureUi.java");assertTrue(s.contains("Challenge yourself with these trivia questions"));assertTrue(s.contains("Do you know the answer?"));assertTrue(s.contains("第二张新帧的系统许可"));assertTrue(s.contains("20:15 至 21:15"));assertFalse(s.contains("setComponent("));}
}
